function prodPlanFail(string$c):never{throw new RuntimeException($c);}
function prodPlanLoad(string$p):array{if(!is_file($p)||is_link($p))prodPlanFail('input');try{$v=json_decode((string)file_get_contents($p),true,64,JSON_THROW_ON_ERROR);}catch(JsonException){prodPlanFail('json');}if(!is_array($v)||array_is_list($v))prodPlanFail('shape');return$v;}
function prodPlanEq(mixed$a,mixed$e,string$c):void{if($a!==$e)prodPlanFail($c);}
function prodPlanCanonical(array$v):string{$w=function(array$x)use(&$w):array{if(array_is_list($x))return array_map(fn($y)=>is_array($y)?$w($y):$y,$x);ksort($x,SORT_STRING);foreach($x as$k=>$y)if(is_array($y))$x[$k]=$w($y);return$x;};return json_encode($w($v),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);}
function prodPlanPrepare(string$mp,string$rp,string$bp,string$tp):array{$m=prodPlanLoad($mp);$r=prodPlanLoad($rp);$b=prodPlanLoad($bp);$t=prodPlanLoad($tp);prodPlanEq($b['binding_state']??null,'EXTERNAL_PRODUCTION_DEPLOYMENT_AUTHORITY_QUALIFIED_NOT_EXECUTED','binding');foreach(['request_id','environment_id','target_descriptor_sha256','release_id','artifact_sha256']as$f)prodPlanEq($b[$f]??null,$r[$f]??null,$f);if(time()>($b['expires_at_unix']??0))prodPlanFail('expired');prodPlanEq($t['target_state']??null,'PRODUCTION_TARGET_CANDIDATE','target');prodPlanEq($t['environment_id']??null,$r['environment_id']??null,'env');prodPlanEq($m['release']['id']??null,$r['release_id']??null,'release');$p=['schema_version'=>1,'plan_state'=>'QUALIFIED_FOR_PRODUCTION_DEPLOYMENT_NOT_EXECUTED_NOT_ACTIVATED','artifact'=>['release_id'=>$r['release_id'],'source_commit'=>$r['source_commit'],'artifact_filename'=>$m['artifact']['filename'],'artifact_sha256'=>$r['artifact_sha256'],'manifest_sha256'=>$r['manifest_sha256']],'staging_promotion_evidence'=>['sha256'=>$r['staging_evidence_sha256'],'same_source_commit_required'=>true],'target'=>['environment_id'=>$r['environment_id'],'runtime_class'=>'production','production'=>true,'production_data_allowed'=>true,'deployment_root'=>$t['filesystem']['deployment_root'],'release_directory'=>rtrim($t['filesystem']['release_root'],'/').'/'.$r['release_id'],'shared_runtime_root'=>$t['filesystem']['shared_runtime_root'],'active_release_pointer'=>$t['filesystem']['active_release_pointer']],'authority_binding'=>['state'=>'EXTERNAL_AUTHORITY_BOUND_TO_EXACT_PRODUCTION_TARGET','authority_id'=>$b['authority_id'],'authority_sha256'=>$b['authority_sha256'],'request_id'=>$b['request_id'],'request_sha256'=>$b['request_sha256'],'target_descriptor_sha256'=>$b['target_descriptor_sha256'],'authorized_at_unix'=>$b['authorized_at_unix'],'expires_at_unix'=>$b['expires_at_unix'],'deployment_allowed'=>true,'production_allowed'=>true,'migration_execution_allowed'=>false,'production_traffic_activation_allowed'=>false],'preflight'=>['required_before_mutation'=>true,'checks'=>['authority_current','artifact_sha256_exact','manifest_exact','staging_evidence_exact','target_descriptor_exact','private_runtime_bindings_present','active_pointer_readback','rollback_target_available','dark_health_endpoint_available']],'execution_order'=>['reverify_authority','reverify_artifact','preserve_current_active_release','extract_immutable_release','bind_private_runtime_configuration','verify_configuration_readback','switch_active_release_pointer','verify_exact_runtime_provenance','verify_dark_non_mutating_health','rehearse_rollback_and_restore_candidate'],'readback_expectations'=>['environment_id'=>$r['environment_id'],'runtime_class'=>'production','running_source_commit'=>$r['source_commit'],'running_artifact_sha256'=>$r['artifact_sha256'],'business_runtime_activation_ready'=>false,'production_traffic_active'=>false],'rollback'=>['required'=>true,'previous_active_release_must_be_preserved'=>true,'rollback_must_be_verified_before_acceptance'=>true,'database_rollback_implied'=>false,'migration_rollback_implied'=>false],'migration'=>['source_included'=>true,'expected_count'=>27,'execution_state'=>'NOT_PERFORMED','execution_authorized'=>false],'traffic_activation'=>['state'=>'NOT_AUTHORIZED','separate_authority_required'=>true,'automatic_activation'=>false],'operational_boundary'=>['environment_deployment'=>'PLAN_ONLY_NOT_EXECUTED','migration27_execution'=>'NOT_PERFORMED','permission_provisioning'=>'NONE','feature_activation'=>'INACTIVE','technical_preview_activation'=>'NOT_AUTHORIZED','production_activation'=>'NOT_AUTHORIZED','updater_activation'=>'INACTIVE','target_selection'=>'NOT_PERFORMED','selected_target'=>null,'producer_dispatch'=>'NOT_PERFORMED'],'attribution'=>'Lab | zefry'];$p['plan_fingerprint']=hash('sha256',prodPlanCanonical($p));return$p;}
function prodPlanWrite(string$p,array$v):void{$j=json_encode($v,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR).PHP_EOL;if(file_put_contents($p,$j,LOCK_EX)!==strlen($j))prodPlanFail('write');@chmod($p,0600);}
if(PHP_SAPI==='cli'&&realpath($_SERVER['SCRIPT_FILENAME']??'')===__FILE__){if($argc!==6)exit(64);try{prodPlanWrite($argv[5],prodPlanPrepare($argv[1],$argv[2],$argv[3],$argv[4]));fwrite(STDOUT,"production_deployment_plan_prepared\n");exit(0);}catch(Throwable$e){fwrite(STDERR,"production_deployment_plan_failed:".$e->getMessage()."\n");exit(1);}}
